import { mdsvex, escapeSvelte } from 'mdsvex';
import remarkGfm from 'remark-gfm';
import adapter from '@sveltejs/adapter-static';
import { createHighlighter } from 'shiki';
import { readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';

// The inline theme script in app.html is not generated by SvelteKit, so its
// hash has to be allowed explicitly. Derived here so edits can't drift.
const appHtml = readFileSync(new URL('./src/app.html', import.meta.url), 'utf8');
const themeScript = appHtml.match(/<script>([\s\S]*?)<\/script>/)[1];
const themeScriptHash = `sha256-${createHash('sha256').update(themeScript).digest('base64')}`;

const highlighter = await createHighlighter({
	themes: ['nord', 'github-light'],
	langs: [
		'python',
		'typescript',
		'javascript',
		'bash',
		'json',
		'css',
		'html',
		'svelte',
		'rust',
		'c',
		'cpp',
		'cmake',
    'toml',
		'yaml',
	]
});

/** @type {import('@sveltejs/kit').Config} */
const config = {
	compilerOptions: {
		// Force runes mode for the project, except for libraries. Can be removed in svelte 6.
		runes: ({ filename }) => (filename.split(/[/\\]/).includes('node_modules') ? undefined : true)
	},
	kit: {
		adapter: adapter({ fallback: '404.html' }),
		// Emitted as a <meta> tag on prerendered pages, with hashes for SvelteKit's
		// own inline scripts. frame-ancestors is set via CloudFront instead, since
		// browsers ignore it in <meta>.
		csp: {
			mode: 'hash',
			directives: {
				'default-src': ['self'],
				'script-src': ['self', themeScriptHash],
				// Shiki emits inline style attributes for syntax highlighting.
				'style-src': ['self', 'unsafe-inline'],
				'img-src': ['self', 'data:'],
				'object-src': ['none'],
				'base-uri': ['self'],
				'form-action': ['self']
			}
		},
		prerender: {
			// No photography entries exist yet, so /photography/[slug] is
			// unreachable by the crawler — warn instead of failing the build.
			handleUnseenRoutes: 'warn'
		}
	},
	preprocess: [
		mdsvex({
			extensions: ['.svx', '.md'],
			remarkPlugins: [remarkGfm],
			highlight: {
				highlighter: (code, lang = 'text') => {
					const html = escapeSvelte(
						highlighter.codeToHtml(code, {
							lang,
							themes: { light: 'github-light', dark: 'nord' },
							defaultColor: false
						})
					);
					return `{@html \`${html}\`}`;
				}
			}
		})
	],
	extensions: ['.svelte', '.svx', '.md']
};

export default config;
